function db():PDO{static $pdo=null;if($pdo instanceof PDO)return $pdo;$path=envv('DATA_DB_PATH')?:__DIR__.'/db/data.db';$parent=dirname($path);if(!is_dir($parent)&&!mkdir($parent,0700,true)&&!is_dir($parent))respond(['error'=>'Tidak dapat membuat folder database.'],500);$deny=$parent.'/.htaccess';if(!is_file($deny))@file_put_contents($deny,"Options -Indexes\nRequire all denied\n");try{$pdo=new PDO('sqlite:'.$path,null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$pdo->exec('PRAGMA foreign_keys=ON; PRAGMA journal_mode=WAL; PRAGMA busy_timeout=5000;');$pdo->exec("CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,email TEXT NOT NULL UNIQUE,name TEXT NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'user' CHECK(role IN ('admin','user')),plan TEXT NOT NULL DEFAULT 'regular' CHECK(plan IN ('regular','premium')),created_at TEXT NOT NULL);");$cols=$pdo->query('PRAGMA table_info(users)')->fetchAll();if(!in_array('plan',array_column($cols,'name'),true))$pdo->exec("ALTER TABLE users ADD COLUMN plan TEXT NOT NULL DEFAULT 'regular'");$pdo->exec("CREATE TABLE IF NOT EXISTS progress(user_id INTEGER PRIMARY KEY,payload TEXT NOT NULL DEFAULT '{}',updated_at TEXT NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);");$pdo->exec("CREATE TABLE IF NOT EXISTS app_settings(setting_key TEXT PRIMARY KEY,setting_value TEXT NOT NULL,updated_at TEXT NOT NULL);");$pdo->exec("CREATE TABLE IF NOT EXISTS audio_assets(id TEXT PRIMARY KEY,user_id INTEGER NOT NULL,client_ref TEXT,mime TEXT NOT NULL,extension TEXT NOT NULL,file_path TEXT NOT NULL,file_size INTEGER NOT NULL,created_at TEXT NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);");seed_admin($pdo);}catch(Throwable $e){respond(['error'=>'SQLite belum tersedia atau database gagal dibuka. Pastikan PHP PDO_SQLITE aktif dan DATA_DB_PATH dapat ditulis.','detail'=>envv('APP_DEBUG')==='1'?$e->getMessage():null],503);}return $p