function seed_admin(PDO $pdo):void{$email=strtolower(trim(envv('ADMIN_EMAIL')));$password=envv('ADMIN_PASSWORD');if($email===''||$password===''||$email==='admin@example.com'||str_contains($password,'replace_with'))return;if(strlen($password)<12)return;$q=$pdo->prepare('SELECT id FROM users WHERE email=?');$q->execute([$email]);if($q->fetch())return;$q=$pdo->prepare('INSERT INTO users(email,name,password_hash,role,plan,created_at) VALUES(?,?,?,?,?,?)');$q->execute([$email,envv('ADMIN_NAME','Administrator'),password_hash($password,PASSWORD_DEFAULT),'admin','premium',gmdate('c')]);}
